import{z as s,x as i,o as t,c as p,q as o,j as B,D as r,d as e,s as A,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"风险叠加：回撤与尾部","description":"","frontmatter":{"title":"风险叠加：回撤与尾部","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/risk-overlay-cap.md","filePath":"quant/risk-overlay-cap.md","lastUpdated":1791063341000}'),d={name:"quant/risk-overlay-cap.md"};function D(h,a,u,m,C,f){const l=i("Mermaid");return t(),p("div",null,[a[2]||(a[2]=o('<h1 id="风险叠加-回撤与尾部" tabindex="-1">风险叠加：回撤与尾部 <a class="header-anchor" href="#风险叠加-回撤与尾部" aria-label="Permalink to &quot;风险叠加：回撤与尾部&quot;">​</a></h1><div class="epigraph"><p>alpha 层回答买什么，overlay 层回答活多久；两层记同一本账，但触发器、数据与权限必须分开。</p><footer>—— 据 Moreira and Muir, Journal of Finance, 2017；Jorion, Value at Risk 整理</footer></div><p><a href="/quant/execution-cost-forecast-cap">上一课</a>把毛权重折成净期望，但成本只修分布的均值；清盘的是路径——从高水位回撤到某个深度，委托就走人了，均值再好看也无人能等到兑现。本课在 alpha 层之上叠一层风险 overlay：回撤控制、波动目标、尾部保护。设计的要点不是各工具的参数怎么调，而是职责分离：overlay 是独立于信号的规则层，触发了就执行，不许拿「alpha 还在」当豁免理由。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>净期望是分布的均值，清盘线是路径的泛函。回撤有两个成分：alpha 衰减，单调地坏；共同因子波动，会回来。overlay 的职责是保住组合等到「会回来」那部分的生存权，同时不去干预信号本身。两种错误要预先排除。其一，没有 overlay，靠信心扛回撤：回撤最深处做的决定，通常是全市场最贵的一笔。其二，用回撤表现直接改信号参数：这既把实盘路径当成了新的验证集，又让触发器本身变成被调参的对象——两层混编后，样本外与保护同时消失。</p><p><span class="marginnote">「泛函」听着吓人，意思很简单：它吃进的不是单个数，而是整条曲线。净期望只问「平均能赚多少」，对路径形状不敏感；清盘线问的是「路径有没有在某一天跌破某个深度」——只要你倒霉的顺序不对，均值再好也出局。这就是期望漂亮却死在半路的原因。</span></p><h3 id="三层叠加-各自的职责" tabindex="-1">三层叠加，各自的职责 <a class="header-anchor" href="#三层叠加-各自的职责" aria-label="Permalink to &quot;三层叠加，各自的职责&quot;">​</a></h3><p>波动目标层：\\(L_t=\\sigma^\\star/\\hat\\sigma_t\\) 把绝对风险钉在政策带上，预测器、再平衡频率与执行方式的取舍见<a href="/quant/vol-targeting">波动目标 vol targeting</a>。回撤层：从高水位回撤带触发降风险，写成状态机——警告、降杠杆、冻结加仓、停机；恢复条件与触发条件同时预指定，否则「跌时减仓、涨时空仓」的棘轮会把每次波动都变成永久损耗。尾部层：用 <a href="/quant/var-methods">VaR</a> 与 <a href="/quant/expected-shortfall">Expected Shortfall</a> 度量尾部预算；该防哪些情景不由想象给出，由<a href="/quant/reverse-stress-test">反向压力测试</a>搜出来——overlay 的触发器至少要能活着穿过那组情景。</p><p><span class="marginnote">尾部保护有 carry：深虚看跌或领口在平静期看着像纯损耗，总被事后「优化掉」。预算必须写进政策并计入 \\(\\mu_{\\mathrm{net}}\\)，而不是每年续期时重新辩论一次。</span></p><p><span class="marginnote">数字实例（波动目标层）：政策带 \\(\\sigma^\\star=10\\%\\)，某日组合预测波动 \\(\\hat\\sigma_t=20\\%\\)，则 \\(L_t=10\\%/20\\%=0.5\\)——总杠杆砍到一半；几天后波动回落到 \\(12.5\\%\\)，杠杆放大回 \\(0.8\\)。注意放大与降杠杆同样要守状态机与流动性约束：波动平静下来时，恰恰是所有人一起加杠杆的拥挤时刻。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>叠加顺序自下而上：先波动目标定总杠杆，再回撤状态机管路径，尾部预算决定对冲腿与仓位上限。杠杆的总上界与<a href="/quant/fractional-kelly-bound">分数 Kelly 的边界</a>取更紧的一个——波动目标的缩放与 Kelly 分数是同一风险预算的两个表达，只让一个当主约束，另一个当检验，叠满是双重乐观。状态机的每一级写明动作与数据：警告级只停新开仓，降杠杆级减参与率再减杠杆，停机级才平仓；触发数据用收盘核算还是日内实时，要在冻结时写清。恢复用带宽加时间窗：回撤修复到高水位下方带内、且持续若干个决策周期，才恢复一级预算。</p>',12)),(t(),B(n,null,{default:r(()=>[A(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PF%5B%22%E7%BB%84%E5%90%88%E5%87%80%E5%80%BC%22%5D%20--%3E%20VT%5B%22%E6%B3%A2%E5%8A%A8%E7%9B%AE%E6%A0%87%E5%AE%9A%E6%80%BB%E6%9D%A0%E6%9D%86%22%5D%0A%20%20VT%20--%3E%20DD%7B%22%E5%9B%9E%E6%92%A4%E7%8A%B6%E6%80%81%E6%9C%BA%22%7D%0A%20%20DD%20--%3E%7C%E5%B8%A6%E5%86%85%7C%20RUN%5B%22%E6%AD%A3%E5%B8%B8%E8%BF%90%E8%A1%8C%22%5D%0A%20%20DD%20--%3E%7C%E8%AD%A6%E5%91%8A%E5%B8%A6%7C%20WRN%5B%22%E5%81%9C%E6%96%B0%E5%BC%80%E4%BB%93%22%5D%0A%20%20DD%20--%3E%7C%E6%B7%B1%E5%B8%A6%7C%20CUT%5B%22%E9%99%8D%E5%8F%82%E4%B8%8E%E7%8E%87%E3%80%81%E9%99%8D%E6%9D%A0%E6%9D%86%22%5D%0A%20%20DD%20--%3E%7C%E6%B8%85%E7%9B%98%E5%B8%A6%7C%20STOP%5B%22%E5%81%9C%E6%9C%BA%E5%A4%8D%E7%9B%98%22%5D%0A%20%20TAIL%5B%22%E5%B0%BE%E9%83%A8%E9%A2%84%E7%AE%97%EF%BC%9AES%20%E4%B8%8E%E5%8E%8B%E5%8A%9B%E6%83%85%E6%99%AF%22%5D%20--%3E%20VT%0A%20%20TAIL%20--%3E%20HEDGE%5B%22%E5%AF%B9%E5%86%B2%E8%85%BF%E4%B8%8E%E4%BB%93%E4%BD%8D%E4%B8%8A%E9%99%90%22%5D%0A%20%20REC%7B%22%E6%81%A2%E5%A4%8D%EF%BC%9A%E5%B8%A6%E5%AE%BD%2B%E6%97%B6%E9%97%B4%E7%AA%97%22%7D%20--%3E%20VT%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("职责分离的机制是避免双重调参：alpha 参数在研究环境冻结，overlay 参数由政策量——回撤容量、清盘线、流动性——导出，两边不共享自由度。触发一次降杠杆，alpha 层不做任何响应；这正是为什么触发器必须可执行：降杠杆发生在流动性变差、成本模型上移的时刻，"),E("a",{href:"/quant/execution-cost-forecast-cap"},"上一课"),e("的保守分位成本在这里自动收紧可执行集。波动目标能成立靠波动聚类与近齐次缩放；但同质规则在拥挤时互相放大抛压，所以降风险优先动参与率与最深的流动性，而不是先甩最贵的那腿。")],-1)),a[5]||(a[5]=E("p",null,"恢复机制是 overlay 最容易漏写的一半。去杠杆付的是确定性成本（错失反弹），恢复决策的对称错误同样致命；带宽加时间窗把「感觉像企稳」翻译成可审计的条件，复核口径与触发相同。",-1)),a[6]||(a[6]=E("p",null,"恢复侧的状态机长这样：",-1)),(t(),B(n,null,{default:r(()=>[A(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20DD%5B%22%E5%9B%9E%E6%92%A4%E4%BF%AE%E5%A4%8D%E4%B8%AD%22%5D%20--%3E%20B%7B%22%E5%9B%9E%E5%88%B0%E9%AB%98%E6%B0%B4%E4%BD%8D%E4%B8%8B%E6%96%B9%E5%B8%A6%E5%AE%BD%E5%86%85%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20WAIT%5B%22%E7%BB%B4%E6%8C%81%E9%99%8D%E9%A3%8E%E9%99%A9%E7%8A%B6%E6%80%81%22%5D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20TW%7B%22%E6%8C%81%E7%BB%AD%E6%BB%A1%E6%97%B6%E9%97%B4%E7%AA%97%EF%BC%9F%22%7D%0A%20%20TW%20--%3E%7C%22%E5%90%A6%22%7C%20WAIT%0A%20%20TW%20--%3E%7C%22%E6%98%AF%22%7C%20UP%5B%22%E6%81%A2%E5%A4%8D%E4%B8%80%E7%BA%A7%E9%A2%84%E7%AE%97%22%5D%0A%20%20UP%20--%3E%20AGAIN%7B%22%E5%86%8D%E6%AC%A1%E7%A9%BF%E5%B8%A6%EF%BC%9F%22%7D%0A%20%20AGAIN%20--%3E%7C%22%E6%98%AF%22%7C%20DD%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">常见误区：用「扣掉 overlay 后收益更高」来质疑这层保护。这就像责怪保险「没理赔就是白交保费」——overlay 的价值只在坏情景兑现时到账：躲过一次 40% 回撤，比每年多赚 2% 值钱得多，因为跌 40% 要涨 67% 才回本，而多数账户等不到那一天。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>overlay 不产生 alpha：波动管理组合的样本内增益不可外推成本层功劳，Moreira–Muir 的机制在条件收益同步上升的信号上会砍掉边缘。跳空日触发器来不及——日内实时也只能在成交可执行后动作，真正的防线是事前的仓位上限与期权腿；A 股 T+1 与涨跌停进一步限制去杠杆速度，缩放腿优先放在可回转工具上。核算上两层用同一本账，KPI 必须分开：alpha 层看净期望，overlay 层看越带次数、执行缺口与存活概率——用净值表现考核 overlay，会诱导它在应该触发时沉默。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>清盘线是路径的泛函；overlay 保生存权，不干预信号定义。</li><li>三层各司其职：波动目标定杠杆，回撤状态机管路径，尾部预算防情景；杠杆上界与分数 Kelly 取更紧的一个。</li><li>触发与恢复同时预指定，恢复用带宽加时间窗，防止棘轮与二次入坑。</li><li>两层不共享自由度：alpha 参数冻结在研究环境，overlay 参数由政策导出。</li><li>出处：Moreira and Muir, <em>JF</em>, 2017；VaR 与 ES 的口径见站内 <a href="/quant/var-methods">VaR：历史、参数、MC</a> 与 <a href="/quant/expected-shortfall">Expected Shortfall</a>。</li></ul>',5))])}const v=s(d,[["render",D]]);export{T as __pageData,v as default};
